import java.util.NoSuchElementException;

public class Main {
    public static class Stack<T> {
        private static class Node<T> {
            private final T value;
            private final Node<T> next;

            private Node(T value, Node<T> next) {
                this.value = value;
                this.next = next;
            }
        }

        private Node<T> top;
        private int size;

        public Stack() {
            top = null;
            size = 0;
        }

        public void push(T value) {
            top = new Node<>(value, top);
            size++;
        }

        public T pop() {
            if (isEmpty()) {
                throw new NoSuchElementException("Stack is empty");
            }
            T value = top.value;
            top = top.next;
            size--;
            return value;
        }

        public T peek() {
            if (isEmpty()) {
                throw new NoSuchElementException("Stack is empty");
            }
            return top.value;
        }

        public boolean isEmpty() {
            return top == null;
        }

        public int size() {
            return size;
        }
    }

    public static <T> void push(Stack<T> stack, T value) {
        stack.push(value);
    }

    public static <T> T pop(Stack<T> stack) {
        return stack.pop();
    }

    public static <T> T peek(Stack<T> stack) {
        return stack.peek();
    }

    public static void main(String[] args) {
        Stack<Integer> stack = new Stack<>();
        push(stack, 1);
        push(stack, 2);
        push(stack, 3);
        System.out.println("peek: " + peek(stack));
        System.out.println("pop: " + pop(stack));
        System.out.println("pop: " + pop(stack));
        System.out.println("size: " + stack.size());
    }
}

